                  identifier: ri!TipoMedioRecepcion[#"urn:appian:record-field:v1:a75f27aa-d47e-45d9-ba93-22dbd2420d00/0e978c6a-cfe0-4a2f-b0cb-511958cd0220"]
                )
              },
              align: "START",
              style: "TOOLBAR_PRIMARY",
              display: "LABEL_AND_ICON"
            ),
            #"SYSTEM_SYSRULES_sectionLayout_v1"(
              label: ri!TipoMedioRecepcion[#"urn:appian:record-field:v1:a75f27aa-d47e-45d9-ba93-22dbd2420d00/67b9f49d-8a67-4c4c-9383-23ad130549bf"],
              contents: {
                #"SYSTEM_SYSRULES_cardLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Código",
                      value: {
                        a!defaultValue(
                                  ri!TipoMedioRecepcion[#"urn:appian:record-field:v1:a75f27aa-d47e-45d9-ba93-22dbd2420d00/c3805b5c-322b-4cf7-8974-132492335248"],
